<script setup lang="ts">
import { computed, nextTick, onMounted, ref, watch } from 'vue';

import { useQuasar, QDate, TouchSwipeValue } from 'quasar';
import { useHutsStore } from '@stores/huts-store';
// The availability spinner state is a module-scope ref, NOT the
// map-catalog store: importing that store here would statically wire
// the eager MainLayout chunk to the map-store cluster and pull the
// MapLibre vendor chunk for crawlers too (follow-up to PR #347).
import { availabilityLoading } from '@stores/map/availability-loading';
// import { useAuthStore } from '@stores/auth-store';
import { date } from 'quasar';
const { formatDate, addToDate, extractDate } = date;
const { selectedDate } = storeToRefs(useHutsStore());
const { removeBookings, fetchHutBookingsGeojson } = useHutsStore();
import { useRouter, useRoute, RouteLocationRaw } from 'vue-router';
import { storeToRefs } from 'pinia';
import { useI18n } from 'vue-i18n';

const { t } = useI18n();
import track from '@services/analytics';
import enUS from 'quasar/lang/en-US.js'; // Adjust the path if necessary

const $router = useRouter();
const $route = useRoute();
const $q = useQuasar();
//const authStore = useAuthStore();
//const selectedDate = ref<string | undefined>(
//  $route.query.date ? ($route.query.date as string) : undefined,
//);

const selectedDateObj = computed<Date | undefined>(() => {
  if (selectedDate.value !== undefined) {
    return extractDate(selectedDate.value, 'DD.MM.YY');
  }
  return undefined;
});

const selectedDateLongName = computed<string>(() => {
  if (selectedDateObj.value !== undefined) {
    return formatDate(selectedDateObj.value, 'D. MMMM YYYY');
  }
  return '';
});
const selectedDateDay = computed<string>(() => {
  if (selectedDateObj.value !== undefined) {
    return formatDate(selectedDateObj.value, 'dddd');
  }
  return t('select_date.placeholder');
});

/** Line 1: relative day name (Today/Tomorrow/weekday), placeholder when empty */
const dateDayLabel = computed(() => {
  if (selectedDateObj.value === undefined) return t('select_date.placeholder');
  const today = new Date();
  const tomorrow = new Date();
  tomorrow.setDate(today.getDate() + 1);
  const sameDay = (a: Date, b: Date) =>
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate();
  if (sameDay(selectedDateObj.value, today)) return t('select_date.today');
  if (sameDay(selectedDateObj.value, tomorrow)) return t('select_date.tomorrow');
  return formatDate(selectedDateObj.value, 'dddd');
});

/** Line 2: full date, subtle hint when empty */
const dateValueLabel = computed(() => {
  if (selectedDateObj.value === undefined) return t('select_date.choose_hint');
  return formatDate(selectedDateObj.value, 'DD.MM.YYYY');
});
const _isMobile = computed(() => {
  return $q.screen.xs;
});
const showMenu = ref(false);

// Allow selecting dates from 2 days before today
const minSelectableDate = computed(() => {
  return formatDate(addToDate(Date.now(), { days: -2 }), 'YYYY/MM/DD');
});

function dateRangeOptions(date: string) {
  return date >= minSelectableDate.value;
}

// hack, because the date always make a transition when i goes to the correct date
// since we use it to set it to the last position we dont want this transition the first time
const noTrans = ref(true);
watch(showMenu, val => {
  if (val == false) {
    noTrans.value = true; // do not use transition the next time
    return;
  }
  let usedDate: number | Date;
  let sel: MonthYear;
  if (leftValue.value !== undefined) {
    sel = leftValue.value;
  } else {
    if (selectedDateObj.value === undefined) {
      usedDate = Date.now();
    } else {
      usedDate = selectedDateObj.value;
    }
    sel = {
      year: parseInt(formatDate(usedDate, 'YYYY')),
      month: parseInt(formatDate(usedDate, 'M')),
    };
  }
  // disable the saved values, we set them again next
  rigthValue.value = undefined;
  leftValue.value = undefined;
  noTrans.value = true;
  nextTick(() => {
    // wait until everyhing is mounted
    if (calLeft.value !== null) {
      calLeft.value.setCalendarTo(sel.year, sel.month);
      updateLeft(sel); // this updates the right calendar
      setTimeout(() => {
        noTrans.value = false; // allow transitions again
      }, 500);
    }
  });
});

function setNewDate(value: string) {
  showMenu.value = false;
  let query = Object.assign({}, $route.query);
  query.date = value;
  let _new_route: RouteLocationRaw = {
    query: query,
    hash: $route.hash,
  };
  removeBookings();
  fetchHutBookingsGeojson({
    date: value,
    days: 4,
  });
  $router.push(_new_route);
}

onMounted(() => {
  if (selectedDate.value === undefined) {
    selectedDate.value = $route.query.date ? ($route.query.date as string) : undefined;
  }
});

watch(
  selectedDate,
  (newDate, oldDate) => {
    if (newDate !== undefined && newDate != oldDate) {
      console.debug(`Booking start date changed to '${newDate}'`);
      const dateObj = extractDate(newDate, 'DD.MM.YY');
      track('booking-date', {
        date: formatDate(dateObj, 'DD.MM.YYYY', enUS.date),
        month: formatDate(dateObj, 'MMMM', enUS.date),
        day: formatDate(dateObj, 'dddd', enUS.date),
        monthDay: formatDate(dateObj, 'MMMM: dddd', enUS.date),
      });
      setNewDate(newDate);
    }
  },
  { immediate: true }
);

function resetDate() {
  removeBookings();
  showMenu.value = false;
  let query = Object.assign({}, $route.query);
  selectedDate.value = undefined;
  delete query.date;
  let _new_route: RouteLocationRaw = {
    query: query,
  };
  $router.push(_new_route);
}

// sync the two calendars, the right needs to have a offset of 1 month
const calLeft = ref<InstanceType<typeof QDate> | null>(null);
const calRigth = ref<InstanceType<typeof QDate> | null>(null);
type MonthYear = { year: number; month: number };
let leftValue = ref<MonthYear | undefined>(undefined);
let rigthValue = ref<MonthYear | undefined>(undefined);
const updateLeft = function (e: MonthYear) {
  leftValue.value = e;
  let month: number = e.month;
  let year: number = e.year;
  month = month >= 12 ? 1 : month + 1;
  year = e.month >= 12 ? year + 1 : year;
  if (calRigth.value != null) {
    if (
      rigthValue.value === undefined ||
      rigthValue.value.month != month ||
      rigthValue.value.year != year
    ) {
      calRigth.value.setCalendarTo(year, month);
      rigthValue.value = { year: year, month: month };
    }
  } else {
    console.warn('Calendar right not ready!');
  }
};

const updateRigth = function (e: MonthYear) {
  rigthValue.value = e;
  let month: number = e.month;
  let year: number = e.year;
  month = month <= 1 ? 12 : month - 1;
  year = e.month <= 1 ? year - 1 : year;
  if (calLeft.value != null) {
    if (
      leftValue.value === undefined ||
      leftValue.value.month != month ||
      leftValue.value.year != year
    ) {
      calLeft.value.setCalendarTo(year, month);
      leftValue.value = { year: year, month: month };
    }
  } else {
    console.warn('Calendar left not ready!');
  }
};

// do the TODAY button disable
const todayDisabled = computed(() => {
  if (leftValue.value !== undefined) {
    return (
      parseInt(formatDate(Date.now(), 'M')) == leftValue.value.month &&
      parseInt(formatDate(Date.now(), 'YYYY')) == leftValue.value.year
    );
  }
  return true;
});
const gotoToday = function () {
  if (calLeft.value !== undefined) {
    const year = parseInt(formatDate(Date.now(), 'YYYY'));
    const month = parseInt(formatDate(Date.now(), 'M'));
    if (calLeft.value != null) {
      calLeft.value.setCalendarTo(year, month);
    }
  }
};

const handleDateSwipe: TouchSwipeValue = e => {
  e.evt?.preventDefault();
  // if ($q.platform.is.mobile && calRigth.value !== null) {
  if (e.direction == 'right') {
    calRigth.value?.offsetCalendar('month', true);
  }
  if (e.direction == 'left') {
    calRigth.value?.offsetCalendar('month', false);
  }
  // }
};

// Check if calendar should show error message
const showCalendarError = computed(() => {
  return false;
  // currently not used anymore
  //// Show calendar (no error) if bookings=1 parameter exists
  //if ($route.query.bookings === '1') {
  //  return false;
  //}
  //// Show calendar (no error) if user is logged in
  //if (authStore.isLoggedIn) {
  //  return false;
  //}

  //// Default: show error
  //return true;
});

// Arrow navigation functions
function incrementDate() {
  if (selectedDateObj.value === undefined) {
    // If no date selected, set to today
    selectedDate.value = formatDate(Date.now(), 'DD.MM.YY');
  } else {
    const newDate = addToDate(selectedDateObj.value, { days: 1 });
    selectedDate.value = formatDate(newDate, 'DD.MM.YY');
  }
}

function decrementDate() {
  if (selectedDateObj.value === undefined) {
    // If no date selected, set to today
    selectedDate.value = formatDate(Date.now(), 'DD.MM.YY');
  } else {
    const newDate = addToDate(selectedDateObj.value, { days: -1 });
    const newDateFormatted = formatDate(newDate, 'YYYY/MM/DD');

    // Don't allow going before minSelectableDate (2 days before today)
    if (newDateFormatted >= minSelectableDate.value) {
      selectedDate.value = formatDate(newDate, 'DD.MM.YY');
    }
  }
}

// Check if decrement is disabled (can't go before 2 days ago)
const decrementDisabled = computed(() => {
  if (selectedDateObj.value === undefined) {
    return false; // Allow setting to today
  }
  const currentDateFormatted = formatDate(selectedDateObj.value, 'YYYY/MM/DD');
  return currentDateFormatted <= minSelectableDate.value;
});

// Handle swipe gestures on date input
const handleDateInputSwipe: TouchSwipeValue = e => {
  e.evt?.preventDefault();
  e.evt?.stopPropagation();
  if (e.direction == 'right' && !decrementDisabled.value) {
    decrementDate();
  }
  if (e.direction == 'left') {
    incrementDate();
  }
};
</script>

<style scoped>
.toolbar-font {
  font-size: medium;
}

.no-text-transform {
  text-transform: none !important;
}
</style>
<style lang="scss">
.no-trans .q-transition {
  &--slide-right,
  &--slide-left,
  &--jump-right,
  &--jump-left {
    &-enter-active,
    &-leave-active {
      --q-transition-duration: 0s;
    }
  }
}
</style>
<template>
  <div class="wd-date-seg">
    <!-- CALENDAR -->
    <q-popup-proxy
      :offset="[10, 1]"
      no-parent-event
      anchor="top start"
      target="#select-date-huts-location"
      v-model="showMenu"
      breakpoint="600"
      transition-show="jump-down"
      transition-hide="jump-up"
    >
      <div>
        <!-- @update:model-value="setNewDate" -->
        <q-card class="dialog-radius wd-menu">
          <div
            class="q-ma-xs z-top text-icon wd-close-btn"
            style="position: absolute; width: 32px; top: 6px; right: 6px"
          >
            <q-btn dense round flat v-close-popup class="wd-close-chip" icon="wd-close"></q-btn>
          </div>
          <!-- HEADER: same slight bg as the footer -->
          <q-list padding class="wd-surface-deep">
            <q-item>
              <!-- <q-item-section avatar>
                <q-avatar size="56px">
                  <img :src="authStore.avatar" />
                </q-avatar>
              </q-item-section> -->
              <!-- NAME - EMAIL -->
              <q-item-section v-if="!showCalendarError">
                <q-item-label class="text-h6 wd-ink-text">{{ selectedDateDay }}</q-item-label>
                <q-item-label class="text-body2 text-primary-100">{{
                  selectedDateLongName
                }}</q-item-label>
              </q-item-section>
              <!-- ERROR MESSAGE HEADER -->
              <q-item-section v-else>
                <q-item-label class="text-h6 wd-ink-text">
                  {{ t('select_date.not_available') }}
                </q-item-label>
              </q-item-section>
            </q-item>
          </q-list>
          <div
            :style="
              showCalendarError
                ? 'max-height: 430px; height: 430px; overflow: hidden'
                : 'max-height: 315px; height: 315px; overflow: hidden'
            "
            v-touch-swipe.mouse.horizontal="handleDateSwipe"
          >
            <!-- ERROR MESSAGE CONTENT -->
            <div
              v-if="showCalendarError"
              style="height: 100%; display: flex; flex-direction: column"
            >
              <img
                src="/images/no_bookings.jpg"
                alt="Sad mood"
                style="width: 370px; height: 180px; object-fit: cover"
              />
              <div
                class="q-pa-lg text-center"
                style="
                  flex: 1;
                  display: flex;
                  flex-direction: column;
                  align-items: center;
                  justify-content: center;
                "
              >
                <p class="text-h6 text-primary-100">{{ t('select_date.error_title') }}</p>
                <p class="text-body2 text-primary-200 q-mt-md">
                  {{ t('select_date.error_restricted') }}<br />
                  {{ t('select_date.error_contact') }}
                  <a
                    href="https://www.sac-cas.ch/de/kontakt/"
                    target="_blank"
                    class="text-accent"
                    >{{ t('select_date.error_contact_link') }}</a
                  >.
                </p>
                <div
                  class="q-mt-md q-pa-sm bg-dark-700 rounded-borders text-center"
                  style="border: 1px solid rgba(255, 193, 7, 0.3)"
                >
                  <p class="text-body2 text-accent q-mb-none" style="font-weight: 500">
                    {{ t('select_date.error_solution') }}
                  </p>
                </div>
                <p class="text-caption text-primary-400 q-mt-md" style="font-size: 0.75rem">
                  {{ t('select_date.alternative') }}
                  <a
                    href="https://www.deine-berge.de/av_reservierung.php"
                    target="_blank"
                    class="text-accent"
                    >deine-berge</a
                  >
                  {{ t('select_date.or') }}
                  <a href="https://www.hut-reservation.org" target="_blank" class="text-accent"
                    >hut-reservation</a
                  >
                </p>
              </div>
            </div>
            <!-- CALENDAR -->
            <div v-else>
              <q-date
                :class="{ 'no-trans': noTrans }"
                v-model="selectedDate"
                minimal
                flat
                :dark="$q.dark.isActive"
                :options="dateRangeOptions"
                first-day-of-week="1"
                :navigation-min-year-month="formatDate(Date.now(), 'YYYY/MM')"
                :navigation-max-year-month="
                  formatDate(addToDate(Date.now(), { years: 2 }), 'YYYY/MM')
                "
                mask="DD.MM.YY"
                color="accent"
                ref="calLeft"
                @navigation="updateLeft"
              >
              </q-date>
              <q-date
                :class="{ 'no-trans': noTrans }"
                v-model="selectedDate"
                v-if="$q.screen.gt.xs"
                minimal
                flat
                :dark="$q.dark.isActive"
                :options="dateRangeOptions"
                ref="calRigth"
                color="accent"
                first-day-of-week="1"
                :navigation-min-year-month="
                  formatDate(addToDate(Date.now(), { month: 1 }), 'YYYY/MM')
                "
                :navigation-max-year-month="
                  formatDate(addToDate(Date.now(), { years: 2, month: 1 }), 'YYYY/MM')
                "
                mask="DD.MM.YY"
                @navigation="updateRigth"
              >
              </q-date>
            </div>
          </div>
          <div class="q-pa-xs row items-center justify-center wd-surface-deep">
            <!-- ERROR FOOTER -->
            <q-btn
              v-if="showCalendarError"
              v-close-popup
              :label="t('select_date.error_dismiss')"
              color="secondary"
              flat
              no-caps
              class="no-text-transform"
            />
            <!-- NORMAL FOOTER -->
            <template v-else>
              <q-btn
                flat
                :disable="todayDisabled"
                @click="gotoToday"
                class="q-mr-md wd-info-text"
                :class="{ 'text-dark-200': todayDisabled }"
                >{{ t('today') }}</q-btn
              >
              <q-btn
                :label="t('reset')"
                color="secondary"
                :disable="selectedDate === undefined"
                flat
                @click="resetDate()"
              />
            </template>
          </div>
        </q-card>
      </div>
    </q-popup-proxy>
    <!-- MOBILE - button -->
    <!-- <q-btn
      icon="fa-solid fa-calendar-days"
      @click="showMenu = true"
      flat
      round
      class="xs"
      dark>
      <q-badge
        v-if="selectedDate"
        color="green-8"
        floating
        transparent
        style="font-size: 7pt"
        >{{ selectedDate }}</q-badge
      >
    </q-btn> -->
    <!-- DESKTOP - textfiled -->
    <div class="wd-date-stepper row no-wrap items-center cursor-pointer">
      <!-- Desktop-only day steppers: ghost arrows flanking the date pill
           (mobile keeps swipe). See .wd-date-step in _topbar.scss. -->
      <button
        v-if="!_isMobile"
        type="button"
        class="wd-date-step wd-date-step--prev"
        :disabled="decrementDisabled"
        :aria-label="t('select_date.previous_day')"
        @click="decrementDate"
      >
        <q-icon size="20px">
          <IconEvaArrowIosBackOutline />
        </q-icon>
      </button>
      <div id="select-date-huts-location" style="flex: 1; position: relative">
        <!-- class="gt-xs" -->
        <!-- Plain 2-line button (no input field): day name + date -->
        <!-- <q-btn flat class="wd-date-btn" icon="wd-calendar" @click="showMenu = true"> -->
        <!--   <span class="wd-date-btn__lines"> -->
        <!--     <span class="wd-date-btn__day" :class="{ 'wd-date-btn__day--empty': selectedDate === undefined }"> -->
        <!--       {{ dateDayLabel }} -->
        <!--     </span> -->
        <!--     <span class="wd-date-btn__date" :class="{ 'wd-date-btn__date--empty': selectedDate === undefined }"> -->
        <!--       {{ dateValueLabel }} -->
        <!--     </span> -->
        <!--   </span> -->
        <!---->
        <!-- </q-btn> -->
        <button type="button" class="wd-date-btn" @click="showMenu = true">
          <!-- Glyph slot: calendar ↔ dots spinner, swapped via v-if with a
               plain opacity fade (150ms) — no transform, no always-mounted
               spinner; the browser is busy fetching tiles during the swap,
               so the transition must stay as cheap as possible. -->
          <transition name="wd-glyph-fade" mode="out-in">
            <q-spinner-dots
              v-if="availabilityLoading"
              size="22px"
              key="spin"
              class="wd-date-btn__spin"
            />
            <q-icon
              v-else
              key="cal"
              name="wd-calendar"
              size="22px"
              class="text-icon wd-date-btn__cal"
              :class="{ 'wd-date-btn__icon--empty': selectedDate === undefined }"
            />
          </transition>
          <span class="wd-date-btn__lines">
            <span
              class="wd-date-btn__day"
              :class="{ 'wd-date-btn__day--empty': selectedDate === undefined }"
            >
              {{ dateDayLabel }}
            </span>
            <span
              class="wd-date-btn__date"
              :class="{ 'wd-date-btn__date--empty': selectedDate === undefined }"
            >
              {{ dateValueLabel }}
            </span>
          </span>
        </button>
        <!-- Swipe overlay -->
        <div
          v-touch-swipe.mouse.horizontal="handleDateInputSwipe"
          style="
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            z-index: 1;
            pointer-events: auto;
          "
          @click="showMenu = true"
        ></div>
      </div>
      <button
        v-if="!_isMobile"
        type="button"
        class="wd-date-step wd-date-step--next"
        :aria-label="t('select_date.next_day')"
        @click="incrementDate"
      >
        <q-icon size="20px">
          <IconEvaArrowIosForwardOutline />
        </q-icon>
      </button>
    </div>
  </div>
</template>
